style.css:
@-moz-document domain("web.whatsapp.com") {
/* ---------- Base canvas: kill solid backgrounds so blur reads through ---------- */
  html, body, #app, ._ak8w /* legacy root wrapper class, harmless if unmatched */ {
    background: transparent !important;
  }

  /* WhatsApp draws a wallpaper pattern behind the chat via a background image/canvas.
     Flattening it here so the glass blur isn't fighting a busy pattern underneath. */
  #main .copyable-area,
  #main > div > div:first-child {
    background-image: none !important;
    background-color: transparent !important;
  }

  /* ---------- Sidebar (chat list) ---------- */
  #pane-side,
  header[data-testid="chatlist-header"],
  div[aria-label="Chat list"] {
    background-color: rgba(20, 20, 24, calc(var(--ws-opacity, 0.55))) !important;
    backdrop-filter: blur(var(--ws-blur, 16px)) saturate(140%);
    -webkit-backdrop-filter: blur(var(--ws-blur, 16px)) saturate(140%);
    border-right: 1px solid rgba(255, 255, 255, 0.08) !important;
  }

  /* Individual chat rows - subtle hover glass */
  div[aria-label="Chat list"] > div > div[role="listitem"] {
    background-color: transparent !important;
    transition: background-color 0.15s ease;
  }
  div[aria-label="Chat list"] > div > div[role="listitem"]:hover {
    background-color: rgba(255, 255, 255, 0.06) !important;
  }

  /* ---------- Top header bars (both sidebar header and open-chat header) ---------- */
  header,
  #main header {
    background-color: rgba(24, 24, 28, calc(var(--ws-opacity, 0.55))) !important;
    backdrop-filter: blur(var(--ws-blur, 16px));
    -webkit-backdrop-filter: blur(var(--ws-blur, 16px));
    border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;
  }

  /* ---------- Main chat panel background ---------- */
  #main {
    background-color: rgba(14, 14, 17, calc(var(--ws-opacity, 0.35))) !important;
  }

  /* ---------- Message bubbles ---------- */
  /* Incoming */
  div.message-in > div.copyable-text,
  div[data-pre-plain-text] > div.copyable-text {
    background-color: rgba(38, 38, 44, 0.55) !important;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 12px !important;
  }

  /* Outgoing - tinted with accent color at low alpha */
  div.message-out > div.copyable-text {
    background-color: color-mix(in srgb, var(--ws-accent, #00A884) 28%, transparent) !important;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px !important;
  }

  /* ---------- Compose / input bar ---------- */
  footer,
  div[data-testid="conversation-compose-box-input"] {
    background-color: rgba(24, 24, 28, calc(var(--ws-opacity, 0.55))) !important;
    backdrop-filter: blur(var(--ws-blur, 16px));
    -webkit-backdrop-filter: blur(var(--ws-blur, 16px));
  }

  div[contenteditable="true"][data-tab] {
    background-color: rgba(255, 255, 255, 0.05) !important;
    border-radius: 20px !important;
  }

  /* ---------- Scrollbars: thin + translucent ---------- */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.15);
    border-radius: 8px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }

  /* ---------- Modals / context menus ---------- */
  div[role="dialog"],
  ul[role="application"],
  div[data-animate-modal-popup="true"] {
    background-color: rgba(24, 24, 28, 0.75) !important;
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
  }
}
